            old_time = ft - vidshift - align_times[trix]
        except:
            nframes = ts.shape[0]
            ft = np.arange(1, nframes + 1) / VIDEO_FR
            old_time = ft - 0.5 - align_times[trix]

        if len(old_time) > 1:
